export const goodMoralUpdateRequest = async (requestId: string,
    goodMoralCorrectionPayload: GoodMoralCorrectionPayload, options?: Parameters<typeof compassFetch>[1]): Promise<goodMoralUpdateRequestResponseSuccess> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
return compassFetch<goodMoralUpdateRequestResponseSuccess>(getGoodMoralUpdateRequestUrl(requestId),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(goodMoralCorrectionPayload)
  }
);}





